/**
 * Type declarations for @fontsource-variable/inter
 *
 * @fontsource ships CSS-only packages with no TS types. We import the
 * package purely for its side effect of registering the font-face CSS.
 * TypeScript 6.0 requires a module declaration to accept side-effect
 * imports of untyped packages.
 *
 * @see https://fontsource.org/
 */
declare module '@fontsource-variable/inter';
